import java.io.DataInputStream;
import java.io.IOException;

public class PD {
    public static void main(String... args) throws IOException {
        Reader reader = new Reader();

        long n = reader.nextInt();
        long m = reader.nextInt();

        long x1 = Math.min(n, m);
        long x2 = Math.max(n, m);

        if(x1 == 1) {
            int memo[] = {0, 1, 2, 3, 2, 1};

            System.out.println(x1 * x2 - (memo[(int)(x2 % 6)]));
        } else if(x1 == 2) {
            if(x2 == 2) {
                System.out.println(0);
            } else if(x2 == 3 || x2 == 7) {
                System.out.println(x1 * x2 - 2);
            } else {
                System.out.println(x1 * x2);
            }
        } else if((x1 * x2) % 2 == 0) {
            System.out.println(x1 * x2);
        } else {
            System.out.println(x1 * x2 - 1);
        }
    }

    static class Reader {
        final private int BUFFER_SIZE = 1 << 16;
        private DataInputStream din;
        private byte[] buffer;
        private int bufferPointer, bytesRead;

        Reader() {
            din = new DataInputStream(System.in);
            buffer = new byte[BUFFER_SIZE];
            bufferPointer = bytesRead = 0;
        }

        String readLine() throws IOException {
            byte[] buf = new byte[64]; // line length
            int cnt = 0, c;
            while ((c = read()) != -1) {
                if (c == '\n')
                    break;
                buf[cnt++] = (byte) c;
            }
            return new String(buf, 0, cnt);
        }

        //Will read words with space as delimiters
        public String nextWord() throws IOException {
            byte[] buf = new byte[64]; // word length

            byte c = read();
            while (c == ' ')
                c = read();
            int cnt = 0;
            do {
                buf[cnt++] = c;
                c = read();
            } while (c != ' ' && c != '\n');

            return new String(buf, 0, cnt);
        }

        public int nextInt() throws IOException {
            int ret = 0;
            byte c = read();
            while (c <= ' ')
                c = read();
            boolean neg = (c == '-');
            if (neg)
                c = read();
            do {
                ret = ret * 10 + c - '0';
            } while ((c = read()) >= '0' && c <= '9');

            if (neg)
                return -ret;
            return ret;
        }

        private void fillBuffer() throws IOException {
            bytesRead = din.read(buffer, bufferPointer = 0, BUFFER_SIZE);
            if (bytesRead == -1)
                buffer[0] = -1;
        }

        private byte read() throws IOException {
            if (bufferPointer == bytesRead)
                fillBuffer();
            return buffer[bufferPointer++];
        }

        public void close() throws IOException {
            if (din == null)
                return;
            din.close();
        }
    }
}

